        {
          "op": "min",
          "field": "Valor do mapa",
          "as": "vmin"
        },
        {
          "op": "max",
          "field": "Valor do mapa",
          "as": "vmax"
        }
      ]
    },
    {
      "calculate": "(datum[''Valor do mapa''] - datum.vmin) / max(datum.vmax - datum.vmin, 1e-9)",
      "as": "t"
    },
    {
      "calculate": "indexof(datum[''Métrica escolhida''], ''ICMS'') >= 0 ? format(datum[''Valor do mapa''], ''.1%'') : format(datum[''Valor do mapa''], ''$,.2f'')",
      "as": "rotulo"
    }
  ],
  "encoding": {
